  ///  retrograde in-track burn has a negative I component).
  List<double>? get DELTA_V => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 16);
  List<double>? get deltaV => DELTA_V;
  ///  Delta-v magnitude, km/s (always >= 0).
  double get MAGNITUDE_KM_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 18, 0.0);
  double get magnitudeKmS => MAGNITUDE_KM_S;
  ///  Burn duration, s; 0 = impulsive.
  double get DURATION_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 20, 0.0);
  double get durationS => DURATION_S;
  ///  Propellant consumed, kg; 0 = not computed.
