///  Relative-motion detail.
class mplRelativeSolution {
  mplRelativeSolution._(this._bc, this._bcOffset);
  factory mplRelativeSolution(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<mplRelativeSolution> reader = _mplRelativeSolutionReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Model reference, e.g. "Koenig-Guffanti-D'Amico ROE STM".
  String? get MODEL_REFERENCE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  String? get modelReference => MODEL_REFERENCE;
  ///  Dynamics INITIAL_ROE was propagated with.
  mplRelativeDynamics get DYNAMICS => mplRelativeDynamics.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 6, 0));
  ///  Dynamics of STATE_TRANSITION and DRAG_COLUMNS.
  mplRelativeDynamics get STM_DYNAMICS => mplRelativeDynamics.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 8, 0));
  mplRelativeDynamics get stmDynamics => STM_DYNAMICS;
  ///  6x6 relative-orbital-element state transition matrix over DURATION_S,
  ///  row-major (36 values), dimensionless (the ROE are dimensionless).
  List<double>? get STATE_TRANSITION => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 10);
  List<double>? get stateTransition => STATE_TRANSITION;
  ///  Drag sensitivity columns, row-major 6 x DRAG_COLUMN_COUNT: entry (i, k)
  ///  is the change in ROE i at DURATION_S per unit of drag rate k, the rates
  ///  being those of mplDifferentialDrag (1/s): k = 0 da-dot, 1 dex-dot, 2
  ///  dey-dot. Unit: seconds (e.g. entry (0, 0) equals
  ///  DURATION_S). J2DragEccentric gives one column (the da-dot column of the
  ///  eccentric model), J2DragArbitrary three. Empty = no drag model.
  List<double>? get DRAG_COLUMNS => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 12);
  List<double>? get dragColumns => DRAG_COLUMNS;
  int get DRAG_COLUMN_COUNT => const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 14, 0);
  int get dragColumnCount => DRAG_COLUMN_COUNT;
  ///  Initial and propagated relative orbital elements (6 values each).
  List<double>? get INITIAL_ROE => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 16);
  List<double>? get initialRoe => INITIAL_ROE;
  List<double>? get PROPAGATED_ROE => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 18);
  List<double>? get propagatedRoe => PROPAGATED_ROE;
  ///  CollisionAvoidance: miss distance the burn achieves, km.
  double get ACHIEVED_MISS_KM => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 20, 0.0);
  double get achievedMissKm => ACHIEVED_MISS_KM;
  ///  CollisionAvoidance: true when the required miss is reachable within the
  ///  available delta-v.
  bool get FEASIBLE => const fb.BoolReader().vTableGet(_bc, _bcOffset, 22, false);
  ///  ApproachCorridor: largest lateral deviation from the corridor axis, km,
  ///  and whether it stays within the corridor.
  double get CORRIDOR_DEVIATION_KM => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 24, 0.0);
  double get corridorDeviationKm => CORRIDOR_DEVIATION_KM;
  bool get WITHIN_CORRIDOR => const fb.BoolReader().vTableGet(_bc, _bcOffset, 26, false);
  bool get withinCorridor => WITHIN_CORRIDOR;

  @override
  String toString() {
    return 'mplRelativeSolution{modelReference: ${modelReference}, DYNAMICS: ${DYNAMICS}, stmDynamics: ${stmDynamics}, stateTransition: ${stateTransition}, dragColumns: ${dragColumns}, dragColumnCount: ${dragColumnCount}, initialRoe: ${initialRoe}, propagatedRoe: ${propagatedRoe}, achievedMissKm: ${achievedMissKm}, FEASIBLE: ${FEASIBLE}, corridorDeviationKm: ${corridorDeviationKm}, withinCorridor: ${withinCorridor}}';
  }
}

class _mplRelativeSolutionReader extends fb.TableReader<mplRelativeSolution> {
  const _mplRelativeSolutionReader();

  @override
  mplRelativeSolution createObject(fb.BufferContext bc, int offset) =>
    mplRelativeSolution._(bc, offset);
}

class mplRelativeSolutionBuilder {
  mplRelativeSolutionBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(12);
  }

  int addModelReferenceOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addDynamics(mplRelativeDynamics? DYNAMICS) {
    fbBuilder.addUint8(1, DYNAMICS?.value);
    return fbBuilder.offset;
  }
  int addStmDynamics(mplRelativeDynamics? STM_DYNAMICS) {
    fbBuilder.addUint8(2, STM_DYNAMICS?.value);
    return fbBuilder.offset;
  }
  int addStateTransitionOffset(int? offset) {
    fbBuilder.addOffset(3, offset);
    return fbBuilder.offset;
  }
  int addDragColumnsOffset(int? offset) {
    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }
  int addDragColumnCount(int? DRAG_COLUMN_COUNT) {
    fbBuilder.addUint8(5, DRAG_COLUMN_COUNT);
    return fbBuilder.offset;
  }
  int addInitialRoeOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }
  int addPropagatedRoeOffset(int? offset) {
    fbBuilder.addOffset(7, offset);
    return fbBuilder.offset;
  }
  int addAchievedMissKm(double? ACHIEVED_MISS_KM) {
    fbBuilder.addFloat64(8, ACHIEVED_MISS_KM);
    return fbBuilder.offset;
  }
  int addFeasible(bool? FEASIBLE) {
    fbBuilder.addBool(9, FEASIBLE);
    return fbBuilder.offset;
  }
  int addCorridorDeviationKm(double? CORRIDOR_DEVIATION_KM) {
    fbBuilder.addFloat64(10, CORRIDOR_DEVIATION_KM);
    return fbBuilder.offset;
  }
  int addWithinCorridor(bool? WITHIN_CORRIDOR) {
    fbBuilder.addBool(11, WITHIN_CORRIDOR);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class mplRelativeSolutionObjectBuilder extends fb.ObjectBuilder {
  final String? _MODEL_REFERENCE;
