  final List<double>? _PROPAGATED_ROE;
  final double? _ACHIEVED_MISS_KM;
  final bool? _FEASIBLE;
  final double? _CORRIDOR_DEVIATION_KM;
  final bool? _WITHIN_CORRIDOR;

  mplRelativeSolutionObjectBuilder({
    String? MODEL_REFERENCE,
    String? modelReference,
    mplRelativeDynamics? DYNAMICS,
    mplRelativeDynamics? STM_DYNAMICS,
    mplRelativeDynamics? stmDynamics,
    List<double>? STATE_TRANSITION,
    List<double>? stateTransition,
    List<double>? DRAG_COLUMNS,
    List<double>? dragColumns,
    int? DRAG_COLUMN_COUNT,
    int? dragColumnCount,
    List<double>? INITIAL_ROE,
    List<double>? initialRoe,
    List<double>? PROPAGATED_ROE,
    List<double>? propagatedRoe,
    double? ACHIEVED_MISS_KM,
    double? achievedMissKm,
    bool? FEASIBLE,
    double? CORRIDOR_DEVIATION_KM,
    double? corridorDeviationKm,
    bool? WITHIN_CORRIDOR,
    bool? withinCorridor,
  })
      : _MODEL_REFERENCE = modelReference ?? MODEL_REFERENCE,
        _DYNAMICS = DYNAMICS,
        _STM_DYNAMICS = stmDynamics ?? STM_DYNAMICS,
        _STATE_TRANSITION = stateTransition ?? STATE_TRANSITION,
        _DRAG_COLUMNS = dragColumns ?? DRAG_COLUMNS,
        _DRAG_COLUMN_COUNT = dragColumnCount ?? DRAG_COLUMN_COUNT,
        _INITIAL_ROE = initialRoe ?? INITIAL_ROE,
        _PROPAGATED_ROE = propagatedRoe ?? PROPAGATED_ROE,
        _ACHIEVED_MISS_KM = achievedMissKm ?? ACHIEVED_MISS_KM,
        _FEASIBLE = FEASIBLE,
        _CORRIDOR_DEVIATION_KM = corridorDeviationKm ?? CORRIDOR_DEVIATION_KM,
        _WITHIN_CORRIDOR = withinCorridor ?? WITHIN_CORRIDOR;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? MODEL_REFERENCEOffset = _MODEL_REFERENCE == null ? null
        : fbBuilder.writeString(_MODEL_REFERENCE!);
    final int? STATE_TRANSITIONOffset = _STATE_TRANSITION == null ? null
        : fbBuilder.writeListFloat64(_STATE_TRANSITION!);
    final int? DRAG_COLUMNSOffset = _DRAG_COLUMNS == null ? null
        : fbBuilder.writeListFloat64(_DRAG_COLUMNS!);
    final int? INITIAL_ROEOffset = _INITIAL_ROE == null ? null
        : fbBuilder.writeListFloat64(_INITIAL_ROE!);
    final int? PROPAGATED_ROEOffset = _PROPAGATED_ROE == null ? null
        : fbBuilder.writeListFloat64(_PROPAGATED_ROE!);
    fbBuilder.startTable(12);
    fbBuilder.addOffset(0, MODEL_REFERENCEOffset);
    fbBuilder.addUint8(1, _DYNAMICS?.value);
    fbBuilder.addUint8(2, _STM_DYNAMICS?.value);
    fbBuilder.addOffset(3, STATE_TRANSITIONOffset);
    fbBuilder.addOffset(4, DRAG_COLUMNSOffset);
    fbBuilder.addUint8(5, _DRAG_COLUMN_COUNT);
    fbBuilder.addOffset(6, INITIAL_ROEOffset);
    fbBuilder.addOffset(7, PROPAGATED_ROEOffset);
    fbBuilder.addFloat64(8, _ACHIEVED_MISS_KM);
    fbBuilder.addBool(9, _FEASIBLE);
    fbBuilder.addFloat64(10, _CORRIDOR_DEVIATION_KM);
    fbBuilder.addBool(11, _WITHIN_CORRIDOR);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
