///  Closed-loop rendezvous detail. Samples are column-major and parallel,
///  one entry (or three, for vectors) per sample, all in the target's RIC
///  axes.
class mplRendezvousSolution {
  mplRendezvousSolution._(this._bc, this._bcOffset);
  factory mplRendezvousSolution(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<mplRendezvousSolution> reader = _mplRendezvousSolutionReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Model reference, e.g. "HCW drift + quintic brake + feedback-linearized
  ///  PD".
  String? get MODEL_REFERENCE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  String? get modelReference => MODEL_REFERENCE;
  ///  Mean motion of the target, rad/s.
  double get MEAN_MOTION_RAD_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 6, 0.0);
  double get meanMotionRadS => MEAN_MOTION_RAD_S;
  ///  Drift-leg initial velocity (solved or given), km/s, 3 values.
  List<double>? get INITIAL_VELOCITY_KM_S => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 8);
  List<double>? get initialVelocityKmS => INITIAL_VELOCITY_KM_S;
  ///  Per-axis proportional (1/s^2) and derivative (1/s) gains, 3 values each.
  List<double>? get KP_PER_S2 => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 10);
  List<double>? get kpPerS2 => KP_PER_S2;
