///  Orbit-geometry detail.
class mplGeometrySolution {
  mplGeometrySolution._(this._bc, this._bcOffset);
  factory mplGeometrySolution(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<mplGeometrySolution> reader = _mplGeometrySolutionReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  OrbitGeometry: the inertial state at the evaluated point (after BURN).
  ephemerisDataLine? get STATE => ephemerisDataLine.reader.vTableGetNullable(_bc, _bcOffset, 4);
  ///  OrbitGeometry: elements at the point (all anomalies and derived fields
  ///  filled); AnomalyConversion: the three anomalies.
  mplElements? get ELEMENTS => mplElements.reader.vTableGetNullable(_bc, _bcOffset, 6);
  ///  Distance from the body centre, km.
  double get RADIUS_KM => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 8, 0.0);
  double get radiusKm => RADIUS_KM;
  ///  The RIC axes at the point, before the burn, as three inertial unit
  ///  vectors R, I, C (9 values, row by row).
  List<double>? get RIC_BASIS => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 10);
  List<double>? get ricBasis => RIC_BASIS;
  ///  The VNC axes at the point, before the burn: V, N, C (9 values).
  List<double>? get VNC_BASIS => const fb.ListReader<double>(fb.Float64Reader()).vTableGetNullable(_bc, _bcOffset, 12);
  List<double>? get vncBasis => VNC_BASIS;
  ///  TimeOfFlight: forward time between the anomalies, s.
  double get TIME_OF_FLIGHT_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 14, 0.0);
  double get timeOfFlightS => TIME_OF_FLIGHT_S;
  ///  DeltaVTransform: the rotated delta-v (its AXES the target axes).
  mplBurn? get BURN => mplBurn.reader.vTableGetNullable(_bc, _bcOffset, 16);

  @override
  String toString() {
    return 'mplGeometrySolution{STATE: ${STATE}, ELEMENTS: ${ELEMENTS}, radiusKm: ${radiusKm}, ricBasis: ${ricBasis}, vncBasis: ${vncBasis}, timeOfFlightS: ${timeOfFlightS}, BURN: ${BURN}}';
  }
}

