  int addBurnOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class mplGeometrySolutionObjectBuilder extends fb.ObjectBuilder {
  final ephemerisDataLineObjectBuilder? _STATE;
  final mplElementsObjectBuilder? _ELEMENTS;
  final double? _RADIUS_KM;
  final List<double>? _RIC_BASIS;
  final List<double>? _VNC_BASIS;
  final double? _TIME_OF_FLIGHT_S;
  final mplBurnObjectBuilder? _BURN;

  mplGeometrySolutionObjectBuilder({
    ephemerisDataLineObjectBuilder? STATE,
    mplElementsObjectBuilder? ELEMENTS,
    double? RADIUS_KM,
    double? radiusKm,
    List<double>? RIC_BASIS,
    List<double>? ricBasis,
    List<double>? VNC_BASIS,
    List<double>? vncBasis,
    double? TIME_OF_FLIGHT_S,
    double? timeOfFlightS,
    mplBurnObjectBuilder? BURN,
  })
      : _STATE = STATE,
        _ELEMENTS = ELEMENTS,
        _RADIUS_KM = radiusKm ?? RADIUS_KM,
        _RIC_BASIS = ricBasis ?? RIC_BASIS,
        _VNC_BASIS = vncBasis ?? VNC_BASIS,
        _TIME_OF_FLIGHT_S = timeOfFlightS ?? TIME_OF_FLIGHT_S,
        _BURN = BURN;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? STATEOffset = _STATE?.getOrCreateOffset(fbBuilder);
    final int? ELEMENTSOffset = _ELEMENTS?.getOrCreateOffset(fbBuilder);
    final int? RIC_BASISOffset = _RIC_BASIS == null ? null
        : fbBuilder.writeListFloat64(_RIC_BASIS!);
    final int? VNC_BASISOffset = _VNC_BASIS == null ? null
        : fbBuilder.writeListFloat64(_VNC_BASIS!);
    final int? BURNOffset = _BURN?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(7);
    fbBuilder.addOffset(0, STATEOffset);
    fbBuilder.addOffset(1, ELEMENTSOffset);
    fbBuilder.addFloat64(2, _RADIUS_KM);
    fbBuilder.addOffset(3, RIC_BASISOffset);
    fbBuilder.addOffset(4, VNC_BASISOffset);
    fbBuilder.addFloat64(5, _TIME_OF_FLIGHT_S);
    fbBuilder.addOffset(6, BURNOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
///  Maneuver Plan - one planning request and the plan that answers it.
class MPL {
  MPL._(this._bc, this._bcOffset);
  factory MPL(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<MPL> reader = _MPLReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Identifier of the plan; empty = not assigned.
  String? get ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  ///  Unix milliseconds the request was made (or the plan produced).
  int get CREATED_AT_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 6, 0);
  int get createdAtMs => CREATED_AT_MS;
  ///  Identifier of the planning service or tool that answered.
  String? get PLANNER => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 8);
  mplProblem get PROBLEM => mplProblem.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 10, 0));
  ///  Unix milliseconds of the plan's start (offset 0); 0 = the plan is in
  ///  relative time only.
  int get PLAN_EPOCH_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 12, 0);
  int get planEpochMs => PLAN_EPOCH_MS;
  ///  The maneuvering object (chaser) and, for relative problems, the target.
  String? get OBJECT_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 14);
  String? get objectId => OBJECT_ID;
  String? get TARGET_OBJECT_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 16);
  String? get targetObjectId => TARGET_OBJECT_ID;
  ///  Inertial frame of every inertial state and Inertial-axes vector; empty =
  ///  the central body's GCRF/EME2000.
  RFM? get REFERENCE_FRAME => RFM.reader.vTableGetNullable(_bc, _bcOffset, 18);
  RFM? get referenceFrame => REFERENCE_FRAME;
  mplRequest? get REQUEST => mplRequest.reader.vTableGetNullable(_bc, _bcOffset, 20);
  mplStatus get STATUS => mplStatus.fromValue(const fb.Uint8Reader().vTableGet(_bc, _bcOffset, 22, 0));
  ///  Stable machine-readable reason when STATUS is not Solved, e.g.
  ///  "invalid-parameter", "no-solution"; empty otherwise.
  String? get ERROR_CODE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 24);
  String? get errorCode => ERROR_CODE;
  String? get ERROR_MESSAGE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 26);
  String? get errorMessage => ERROR_MESSAGE;
  ///  The burns, in time order.
  List<mplBurn>? get BURNS => const fb.ListReader<mplBurn>(mplBurn.reader).vTableGetNullable(_bc, _bcOffset, 28);
  ///  The arcs, in time order.
  List<mplArc>? get ARCS => const fb.ListReader<mplArc>(mplArc.reader).vTableGetNullable(_bc, _bcOffset, 30);
  ///  Total delta-v: the sum of burn magnitudes (the propellant budget), km/s.
  double get TOTAL_DELTA_V_KM_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 32, 0.0);
  double get totalDeltaVKmS => TOTAL_DELTA_V_KM_S;
  ///  Time from the plan's start to its end, s.
  double get TOTAL_TIME_S => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 34, 0.0);
  double get totalTimeS => TOTAL_TIME_S;
  ///  Propellant for the whole plan, kg; 0 = not computed.
  double get TOTAL_DELTA_MASS_KG => const fb.Float64Reader().vTableGet(_bc, _bcOffset, 36, 0.0);
  double get totalDeltaMassKg => TOTAL_DELTA_MASS_KG;
  ///  Solver evidence for the plan as a whole.
  mplSolver? get SOLVER => mplSolver.reader.vTableGetNullable(_bc, _bcOffset, 38);
  ///  Options weighed, including the selected one.
  List<mplOption>? get OPTIONS => const fb.ListReader<mplOption>(mplOption.reader).vTableGetNullable(_bc, _bcOffset, 40);
  ///  The whole plan's sampled trajectory; empty = not sampled.
  mplTrajectory? get TRAJECTORY => mplTrajectory.reader.vTableGetNullable(_bc, _bcOffset, 42);
  mplPhasingSolution? get PHASING => mplPhasingSolution.reader.vTableGetNullable(_bc, _bcOffset, 44);
  mplRelativeSolution? get RELATIVE => mplRelativeSolution.reader.vTableGetNullable(_bc, _bcOffset, 46);
  mplRendezvousSolution? get RENDEZVOUS => mplRendezvousSolution.reader.vTableGetNullable(_bc, _bcOffset, 48);
  mplGeometrySolution? get GEOMETRY => mplGeometrySolution.reader.vTableGetNullable(_bc, _bcOffset, 50);

  @override
  String toString() {
    return 'MPL{ID: ${ID}, createdAtMs: ${createdAtMs}, PLANNER: ${PLANNER}, PROBLEM: ${PROBLEM}, planEpochMs: ${planEpochMs}, objectId: ${objectId}, targetObjectId: ${targetObjectId}, referenceFrame: ${referenceFrame}, REQUEST: ${REQUEST}, STATUS: ${STATUS}, errorCode: ${errorCode}, errorMessage: ${errorMessage}, BURNS: ${BURNS}, ARCS: ${ARCS}, totalDeltaVKmS: ${totalDeltaVKmS}, totalTimeS: ${totalTimeS}, totalDeltaMassKg: ${totalDeltaMassKg}, SOLVER: ${SOLVER}, OPTIONS: ${OPTIONS}, TRAJECTORY: ${TRAJECTORY}, PHASING: ${PHASING}, RELATIVE: ${RELATIVE}, RENDEZVOUS: ${RENDEZVOUS}, GEOMETRY: ${GEOMETRY}}';
  }
}

class _MPLReader extends fb.TableReader<MPL> {
  const _MPLReader();

  @override
  MPL createObject(fb.BufferContext bc, int offset) =>
    MPL._(bc, offset);
}

