class MPLObjectBuilder extends fb.ObjectBuilder {
  final String? _ID;
  final int? _CREATED_AT_MS;
  final String? _PLANNER;
  final mplProblem? _PROBLEM;
  final int? _PLAN_EPOCH_MS;
  final String? _OBJECT_ID;
  final String? _TARGET_OBJECT_ID;
  final RFMObjectBuilder? _REFERENCE_FRAME;
  final mplRequestObjectBuilder? _REQUEST;
  final mplStatus? _STATUS;
  final String? _ERROR_CODE;
  final String? _ERROR_MESSAGE;
  final List<mplBurnObjectBuilder>? _BURNS;
  final List<mplArcObjectBuilder>? _ARCS;
  final double? _TOTAL_DELTA_V_KM_S;
  final double? _TOTAL_TIME_S;
  final double? _TOTAL_DELTA_MASS_KG;
  final mplSolverObjectBuilder? _SOLVER;
  final List<mplOptionObjectBuilder>? _OPTIONS;
  final mplTrajectoryObjectBuilder? _TRAJECTORY;
  final mplPhasingSolutionObjectBuilder? _PHASING;
  final mplRelativeSolutionObjectBuilder? _RELATIVE;
  final mplRendezvousSolutionObjectBuilder? _RENDEZVOUS;
  final mplGeometrySolutionObjectBuilder? _GEOMETRY;

  MPLObjectBuilder({
    String? ID,
    int? CREATED_AT_MS,
    int? createdAtMs,
    String? PLANNER,
    mplProblem? PROBLEM,
    int? PLAN_EPOCH_MS,
    int? planEpochMs,
    String? OBJECT_ID,
    String? objectId,
    String? TARGET_OBJECT_ID,
    String? targetObjectId,
    RFMObjectBuilder? REFERENCE_FRAME,
    RFMObjectBuilder? referenceFrame,
    mplRequestObjectBuilder? REQUEST,
    mplStatus? STATUS,
    String? ERROR_CODE,
    String? errorCode,
    String? ERROR_MESSAGE,
    String? errorMessage,
    List<mplBurnObjectBuilder>? BURNS,
    List<mplArcObjectBuilder>? ARCS,
    double? TOTAL_DELTA_V_KM_S,
    double? totalDeltaVKmS,
    double? TOTAL_TIME_S,
    double? totalTimeS,
    double? TOTAL_DELTA_MASS_KG,
    double? totalDeltaMassKg,
    mplSolverObjectBuilder? SOLVER,
    List<mplOptionObjectBuilder>? OPTIONS,
    mplTrajectoryObjectBuilder? TRAJECTORY,
    mplPhasingSolutionObjectBuilder? PHASING,
    mplRelativeSolutionObjectBuilder? RELATIVE,
    mplRendezvousSolutionObjectBuilder? RENDEZVOUS,
    mplGeometrySolutionObjectBuilder? GEOMETRY,
  })
      : _ID = ID,
        _CREATED_AT_MS = createdAtMs ?? CREATED_AT_MS,
        _PLANNER = PLANNER,
        _PROBLEM = PROBLEM,
        _PLAN_EPOCH_MS = planEpochMs ?? PLAN_EPOCH_MS,
        _OBJECT_ID = objectId ?? OBJECT_ID,
        _TARGET_OBJECT_ID = targetObjectId ?? TARGET_OBJECT_ID,
        _REFERENCE_FRAME = referenceFrame ?? REFERENCE_FRAME,
        _REQUEST = REQUEST,
        _STATUS = STATUS,
        _ERROR_CODE = errorCode ?? ERROR_CODE,
        _ERROR_MESSAGE = errorMessage ?? ERROR_MESSAGE,
        _BURNS = BURNS,
        _ARCS = ARCS,
        _TOTAL_DELTA_V_KM_S = totalDeltaVKmS ?? TOTAL_DELTA_V_KM_S,
        _TOTAL_TIME_S = totalTimeS ?? TOTAL_TIME_S,
        _TOTAL_DELTA_MASS_KG = totalDeltaMassKg ?? TOTAL_DELTA_MASS_KG,
        _SOLVER = SOLVER,
        _OPTIONS = OPTIONS,
        _TRAJECTORY = TRAJECTORY,
        _PHASING = PHASING,
        _RELATIVE = RELATIVE,
        _RENDEZVOUS = RENDEZVOUS,
        _GEOMETRY = GEOMETRY;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? IDOffset = _ID == null ? null
        : fbBuilder.writeString(_ID!);
    final int? PLANNEROffset = _PLANNER == null ? null
        : fbBuilder.writeString(_PLANNER!);
    final int? OBJECT_IDOffset = _OBJECT_ID == null ? null
        : fbBuilder.writeString(_OBJECT_ID!);
    final int? TARGET_OBJECT_IDOffset = _TARGET_OBJECT_ID == null ? null
        : fbBuilder.writeString(_TARGET_OBJECT_ID!);
    final int? REFERENCE_FRAMEOffset = _REFERENCE_FRAME?.getOrCreateOffset(fbBuilder);
    final int? REQUESTOffset = _REQUEST?.getOrCreateOffset(fbBuilder);
    final int? ERROR_CODEOffset = _ERROR_CODE == null ? null
        : fbBuilder.writeString(_ERROR_CODE!);
    final int? ERROR_MESSAGEOffset = _ERROR_MESSAGE == null ? null
        : fbBuilder.writeString(_ERROR_MESSAGE!);
    final int? BURNSOffset = _BURNS == null ? null
        : fbBuilder.writeList(_BURNS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? ARCSOffset = _ARCS == null ? null
        : fbBuilder.writeList(_ARCS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? SOLVEROffset = _SOLVER?.getOrCreateOffset(fbBuilder);
    final int? OPTIONSOffset = _OPTIONS == null ? null
        : fbBuilder.writeList(_OPTIONS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? TRAJECTORYOffset = _TRAJECTORY?.getOrCreateOffset(fbBuilder);
    final int? PHASINGOffset = _PHASING?.getOrCreateOffset(fbBuilder);
    final int? RELATIVEOffset = _RELATIVE?.getOrCreateOffset(fbBuilder);
    final int? RENDEZVOUSOffset = _RENDEZVOUS?.getOrCreateOffset(fbBuilder);
    final int? GEOMETRYOffset = _GEOMETRY?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(24);
    fbBuilder.addOffset(0, IDOffset);
    fbBuilder.addInt64(1, _CREATED_AT_MS);
    fbBuilder.addOffset(2, PLANNEROffset);
    fbBuilder.addUint8(3, _PROBLEM?.value);
    fbBuilder.addInt64(4, _PLAN_EPOCH_MS);
    fbBuilder.addOffset(5, OBJECT_IDOffset);
    fbBuilder.addOffset(6, TARGET_OBJECT_IDOffset);
    fbBuilder.addOffset(7, REFERENCE_FRAMEOffset);
    fbBuilder.addOffset(8, REQUESTOffset);
    fbBuilder.addUint8(9, _STATUS?.value);
    fbBuilder.addOffset(10, ERROR_CODEOffset);
    fbBuilder.addOffset(11, ERROR_MESSAGEOffset);
    fbBuilder.addOffset(12, BURNSOffset);
    fbBuilder.addOffset(13, ARCSOffset);
    fbBuilder.addFloat64(14, _TOTAL_DELTA_V_KM_S);
    fbBuilder.addFloat64(15, _TOTAL_TIME_S);
    fbBuilder.addFloat64(16, _TOTAL_DELTA_MASS_KG);
    fbBuilder.addOffset(17, SOLVEROffset);
    fbBuilder.addOffset(18, OPTIONSOffset);
    fbBuilder.addOffset(19, TRAJECTORYOffset);
    fbBuilder.addOffset(20, PHASINGOffset);
    fbBuilder.addOffset(21, RELATIVEOffset);
    fbBuilder.addOffset(22, RENDEZVOUSOffset);
    fbBuilder.addOffset(23, GEOMETRYOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
